mapper.select:
SELECT id, display_name, client_type, reserved_service_key, allowed_scopes,
       client_status, created_at, updated_at, revoked_at
FROM iam_oauth_clients
WHERE strpos(display_name, #{name}) > 0
AND client_type = #{type}
AND client_status = #{status}
AND id > #{afterId}
ORDER BY id ASC LIMIT #{limit}

SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM iam_oauth_client_secrets
    WHERE client_id = #{clientId}
      AND revoked_at IS NULL
      AND valid_until > #{at}
) THEN 1 ELSE 0 END

mapper.update:
UPDATE iam_oauth_client_secrets
SET valid_until = #{validUntil}
WHERE client_id = #{clientId} AND revoked_at IS NULL AND valid_until IS NULL

UPDATE iam_oauth_clients
SET updated_at = #{updatedAt}
WHERE id = #{clientId} AND client_status = 'ACTIVE'

UPDATE iam_oauth_client_secrets
SET revoked_at = #{revokedAt}
WHERE id = #{secretId} AND client_id = #{clientId} AND revoked_at IS NULL

UPDATE iam_oauth_clients
SET client_status = 'REVOKED', revoked_at = #{revokedAt}, updated_at = #{revokedAt}
WHERE id = #{clientId} AND client_status = 'ACTIVE'

UPDATE iam_oauth_client_secrets
SET revoked_at = #{revokedAt}
WHERE client_id = #{clientId} AND revoked_at IS NULL
